typed_term = (f_term | memory_allocation_term | memory_bool_term | memory_integer_term | memory_storage_1_term | memory_storage_2_term | memory_storage_3_term | memory_storage_4_term | memory_storage_5_term | memory_storage_6_term | memory_storage_7_term | memory_string_term | t_term | bool_term | some_term | option_term | result_term | builder_term | opaque_1_term | opaque_2_term) ;
